import{_ as p,a0 as o,w as h,s as d,I as a,a1 as n,A as t,x as i,ao as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"如何在 CentOS 8/RHEL 8 上安裝 Ansible（自動化工具） | LCTT x X-CMD","titleTemplate":false,"description":"如何在 CentOS 8/RHEL 8 上安裝 Ansible（自動化工具） | LCTT (201912) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 CentOS 8/RHEL 8 上安裝 Ansible（自動化工具） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 CentOS 8/RHEL 8 上安裝 Ansible（自動化工具） | LCTT (201912) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201912/20191125 How to Install Ansible (Automation Tool) on CentOS 8-RHEL 8","title":"如何在 CentOS 8/RHEL 8 上安裝 Ansible（自動化工具）","tag":"201912","desc":""},"relativePath":"201912/20191125 How to Install Ansible (Automation Tool) on CentOS 8-RHEL 8.md","filePath":"[post].md"}'),r={name:"201912/20191125 How to Install Ansible (Automation Tool) on CentOS 8-RHEL 8.md"};function b(c,s,u,g,k,f){const e=o("Link");return h(),d("div",null,[a("p",null,[n(e,{href:"collector:",title:"lujun9972"},{default:t(()=>[...s[0]||(s[0]=[i("#",-1)])]),_:1}),s[5]||(s[5]=i(": subject: (How to Install Ansible (Automation Tool) on CentOS 8/RHEL 8) ",-1)),n(e,{href:"collector:",title:"lujun9972"},{default:t(()=>[...s[1]||(s[1]=[i("#",-1)])]),_:1}),s[6]||(s[6]=i(": via: (",-1)),n(e,{href:"https://www.linuxtechi.com/install-ansible-centos-8-rhel-8/"},{default:t(()=>[...s[2]||(s[2]=[i("https://www.linuxtechi.com/install-ansible-centos-8-rhel-8/",-1)])]),_:1}),s[7]||(s[7]=i(") ",-1)),n(e,{href:"collector:",title:"lujun9972"},{default:t(()=>[...s[3]||(s[3]=[i("#",-1)])]),_:1}),s[8]||(s[8]=i(": author: (Pradeep Kumar ",-1)),n(e,{href:"https://www.linuxtechi.com/author/pradeep/"},{default:t(()=>[...s[4]||(s[4]=[i("https://www.linuxtechi.com/author/pradeep/",-1)])]),_:1}),s[9]||(s[9]=i(")",-1))]),s[28]||(s[28]=l('<h1 id="如何在-centos-8-rhel-8-上安裝-ansible-自動化工具" tabindex="-1">如何在 CentOS 8/RHEL 8 上安裝 Ansible（自動化工具） <a class="header-anchor" href="#如何在-centos-8-rhel-8-上安裝-ansible-自動化工具" aria-label="Permalink to “如何在 CentOS 8/RHEL 8 上安裝 Ansible（自動化工具）”">​</a></h1><p>Ansible 是給 Linux 系統管理員使用的出色自動化工具。它是一種開源配置工具，能讓系統管理員可以從一箇中心節點（即 Ansible 服務器）管理數百台服務器。將 Ansible 與 Puppet、Chef 和 Salt 等類似工具進行比較時，它是首選的配置工具，因為它不需要任何代理，並且可以工作在 SSH 和 python 上。</p><p><img src="https://img.linux.net.cn/data/attachment/album/201912/01/223012czkxt6dhku6snhxn.jpg" alt=""></p><p>在本教程中，我們將學習如何在 CentOS 8 和 RHEL 8 系統上安裝和使用 Ansble。</p><p>Ansible 實驗環境信息：</p><ul><li>最小化安裝的 CentOS 8 / RHEL 8 服務器（192.168.1.10），且有互聯網連接</li><li>兩個 Ansible 節點 - Ubuntu 18.04 LTS （192.168.1.20） 和 CentOS 7 （192.168.1.30）</li></ul><h3 id="centos-8-上的-ansible-安裝步驟" tabindex="-1">CentOS 8 上的 Ansible 安裝步驟 <a class="header-anchor" href="#centos-8-上的-ansible-安裝步驟" aria-label="Permalink to “CentOS 8 上的 Ansible 安裝步驟”">​</a></h3>',7)),a("p",null,[s[11]||(s[11]=i("Ansible 包不在 CentOS 8 默認的軟件包倉庫中。因此，我們需要執行以下命令啓用 ",-1)),n(e,{href:"http://www.linuxtechi.com/enable-epel-repo-centos8-rhel8-server/"},{default:t(()=>[...s[10]||(s[10]=[i("EPEL 倉庫",-1)])]),_:1}),s[12]||(s[12]=i("：",-1))]),s[29]||(s[29]=l(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]$ sudo dnf install https://dl.fedoraproject.org/pub/epel/epel-release-latest-8.noarch.rpm -y</span></span></code></pre></div><p>啓用 epel 倉庫後，執行以下 <code>dnf</code> 命令安裝 Ansible：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]$ sudo dnf install ansible</span></span></code></pre></div><p>上面命令的輸出：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/11/dnf-install-ansible-centos8-1536x652.png" alt="dnf-install-ansible-centos8"></p><p>成功安裝 Ansible 後，運行以下命令驗證它的版本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]$ sudo ansible --version</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/11/Ansible-version-CentOS8.png" alt="Ansible-version-CentOS8"></p><p>上面的輸出確認在 CentOS 8 上安裝完成。</p><p>讓我們看下 RHEL 8 系統。</p><h3 id="rhel-8-上的-ansible-安裝步驟" tabindex="-1">RHEL 8 上的 Ansible 安裝步驟 <a class="header-anchor" href="#rhel-8-上的-ansible-安裝步驟" aria-label="Permalink to “RHEL 8 上的 Ansible 安裝步驟”">​</a></h3><p>如果你有有效的 RHEL 8 訂閲，請使用以下訂閲管理器命令啓用 Ansble 倉庫：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]$ sudo subscription-manager repos --enable ansible-2.8-for-rhel-8-x86_64-rpms</span></span></code></pre></div><p>啓用倉庫後，執行以下 <code>dnf</code> 命令安裝 Ansible：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]$ sudo dnf install ansible -y</span></span></code></pre></div><p>安裝 Ansible 及其依賴包後，執行以下命令來驗證它的版本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]$ sudo ansible --version</span></span></code></pre></div><h3 id="在-centos-8-rhel-8-上通過-pip3-安裝-ansible-的可選方法" tabindex="-1">在 CentOS 8 / RHEL 8 上通過 pip3 安裝 Ansible 的可選方法 <a class="header-anchor" href="#在-centos-8-rhel-8-上通過-pip3-安裝-ansible-的可選方法" aria-label="Permalink to “在 CentOS 8 / RHEL 8 上通過 pip3 安裝 Ansible 的可選方法”">​</a></h3><p>如果你希望使用 <code>pip</code>（Python 的包管理器）安裝 Ansible，請首先使用以下命令安裝 pyhton3 和 python3-pip 包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]$ sudo dnf install python3 python3-pip -y</span></span></code></pre></div><p>安裝 python3 後，運行以下命令來驗證它的版本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]$ python3 -V</span></span>
<span class="line"><span>Python 3.6.8</span></span>
<span class="line"><span>[root@linuxtechi ~]$</span></span></code></pre></div><p>用下面的 <code>pip3</code> 命令安裝 Ansible：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]$ pip3 install ansible --user</span></span></code></pre></div><p>輸出：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/11/Ansible-Install-pip3-centos8-1536x545.png" alt="Ansible-Install-pip3-centos8"></p><p>上面的輸出確認 Ansible 已成功使用 <code>pip3</code> 安裝。讓我們看下如何使用 Ansible。</p><h3 id="如何使用-ansible-自動化工具" tabindex="-1">如何使用 Ansible 自動化工具？ <a class="header-anchor" href="#如何使用-ansible-自動化工具" aria-label="Permalink to “如何使用 Ansible 自動化工具？”">​</a></h3><p>當我們使用 <code>yum</code> 或 <code>dnf</code> 命令安裝 Ansible 時，它的配置文件、清單文件和角色目錄會自動在 <code>/etc/ansible</code> 文件夾下創建。</p><p>讓我們添加一個名稱為 <code>labservers</code> 的組，並在 <code>/etc/ansible/hosts</code> 文件中給該組添加上述的 Ubuntu 18.04 和 CentOS 7 系統的 IP 地址：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]$ sudo vi /etc/ansible/hosts</span></span>
<span class="line"><span>…</span></span>
<span class="line"><span>[labservers]</span></span>
<span class="line"><span>192.168.1.20</span></span>
<span class="line"><span>192.168.1.30</span></span>
<span class="line"><span>…</span></span></code></pre></div><p>保存並退出文件。</p><p>更新清單文件（<code>/etc/ansible/hosts</code>）後，將用户的 ssh 公鑰放到屬於 <code>labservers</code> 組的遠程系統。</p><p>讓我們首先使用 <code>ssh-keygen</code> 命令生成本地用户的公鑰和私鑰：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]$ ssh-keygen</span></span></code></pre></div><p>現在使用以下命令在 Ansible 服務器及其客户端之間交換公鑰：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]$ ssh-copy-id root@linuxtechi</span></span>
<span class="line"><span>[root@linuxtechi ~]$ ssh-copy-id root@linuxtechi</span></span></code></pre></div><p>現在，讓我們嘗試幾個 Ansible 命令，首先使用 <code>ping</code> 模組驗證 Ansible 服務器與客户端的連接：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]$ ansible -m ping &quot;labservers&quot;</span></span></code></pre></div><p>注意： 如果我們沒有在上面的命令中指定清單文件，那麼它將引用默認主機文件（即 <code>/etc/ansible/hosts</code>）。</p><p>輸出：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/11/ansible-ping-module-centos8.png" alt="ansible-ping-module-centos8"></p><p>讓我們使用 Ansible shell 命令檢查每個客户端的內核版本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]$ ansible -m command -a &quot;uname -r&quot; &quot;labservers&quot;</span></span>
<span class="line"><span>192.168.1.30 | CHANGED | rc=0 &gt;&gt;</span></span>
<span class="line"><span>4.15.0-20-generic</span></span>
<span class="line"><span>192.168.1.20 | CHANGED | rc=0 &gt;&gt;</span></span>
<span class="line"><span>3.10.0-327.el7.x86_64</span></span>
<span class="line"><span>[root@linuxtechi ~]$</span></span></code></pre></div><p>使用以下命令列出清單文件中的所有主機：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]$ ansible all -i /etc/ansible/hosts --list-hosts</span></span>
<span class="line"><span>  hosts (4):</span></span>
<span class="line"><span>    192.168.100.1</span></span>
<span class="line"><span>    192.168.100.10</span></span>
<span class="line"><span>    192.168.1.20</span></span>
<span class="line"><span>    192.168.1.30</span></span>
<span class="line"><span>[root@linuxtechi ~]$</span></span></code></pre></div><p>使用以下 Ansible 命令僅列出 <code>labservers</code> 組中的主機：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi ~]$ ansible labservers -i /etc/ansible/hosts --list-hosts</span></span>
<span class="line"><span>  hosts (2):</span></span>
<span class="line"><span>    192.168.1.20</span></span>
<span class="line"><span>    192.168.1.30</span></span>
<span class="line"><span>[root@linuxtechi ~]$</span></span></code></pre></div><p>本文就是這些了，我們成功演示瞭如何在 CentOS 8 和 RHEL 8 系統中安裝和使用 Ansible。請分享你的反饋和意見。</p><hr>`,50)),a("p",null,[s[14]||(s[14]=i("via: ",-1)),n(e,{href:"https://www.linuxtechi.com/install-ansible-centos-8-rhel-8/"},{default:t(()=>[...s[13]||(s[13]=[i("https://www.linuxtechi.com/install-ansible-centos-8-rhel-8/",-1)])]),_:1})]),a("p",null,[s[19]||(s[19]=i("作者：",-1)),n(e,{href:"https://www.linuxtechi.com/author/pradeep/"},{default:t(()=>[...s[15]||(s[15]=[i("Pradeep Kumar",-1)])]),_:1}),s[20]||(s[20]=i(" 選題：",-1)),n(e,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[16]||(s[16]=[i("lujun9972",-1)])]),_:1}),s[21]||(s[21]=i(" 譯者：",-1)),n(e,{href:"https://github.com/geekpi"},{default:t(()=>[...s[17]||(s[17]=[i("geekpi",-1)])]),_:1}),s[22]||(s[22]=i(" 校對：",-1)),n(e,{href:"https://github.com/wxy"},{default:t(()=>[...s[18]||(s[18]=[i("wxy",-1)])]),_:1})]),a("p",null,[s[25]||(s[25]=i("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[23]||(s[23]=[i("LCTT",-1)])]),_:1}),s[26]||(s[26]=i(" 原創編譯，",-1)),n(e,{href:"https://linux.cn/"},{default:t(()=>[...s[24]||(s[24]=[i("Linux中國",-1)])]),_:1}),s[27]||(s[27]=i(" 榮譽推出",-1))])])}const y=p(r,[["render",b]]);export{x as __pageData,y as default};
